package com.marinainsaurralde.plango.model;
import java.util.Collections;import java.util.List;
public final class GrupoUbicacion {private final double latitud,longitud;private final List<Plan> planes;public GrupoUbicacion(double lat,double lon,List<Plan> planes){latitud=lat;longitud=lon;this.planes=Collections.unmodifiableList(planes);}public double getLatitud(){return latitud;}public double getLongitud(){return longitud;}public List<Plan> getPlanes(){return planes;}public int size(){return planes.size();}public Plan getFirst(){return planes.get(0);}public String getInstalacion(){for(Plan p:planes)if(p.getNombreInstalacion()!=null&&!p.getNombreInstalacion().trim().isEmpty())return p.getNombreInstalacion();return null;}}
